    m._v1ZemRawG=rawG;m._v1ZemCapG=capG;m._v1ZemDeliveredCmdG=Math.hypot(ax,ay,az)/G0;
    return {
      ax, ay, az,
      predictedCPA: zMag,
      predictedCPATime: tgo
    };
  }

